import React, {
  forwardRef,
  ReactElement,
  createRef,
  useState,
  useEffect,
} from 'react';
import classNames from 'classnames';
import { useForm } from '@teambit/base-react.forms.form';
import { NoticeTooltip, Accent } from '@teambit/design.overlays.notice-tooltip';
import { Icon } from '@teambit/design.elements.icon';
import { getAccent, ColorAccentProps } from './color-accent';
import styles from './input-text.module.scss';
import sizes from './sizes.module.scss';

export type InputTextProps = {
  /**
   * An optional Icon element to be render at the end of the input, can be an Image or an Icon.
   */
  icon?: ReactElement;
  /**
   * Override input styles.
   */
  inputClass?: string;
  /**
   * Override message styles.
   */
  messageClass?: string;
  /**
   * Message text.
   */
  message?: string | null | undefined;
  /**
   * Active the label animation from "placeholder" to top position.
   */
  activeLabel?: boolean;
  /**
   * input sizes
   */
  inputSize?: 's' | 'm' | 'l' | null;
} & ColorAccentProps &
  React.InputHTMLAttributes<HTMLInputElement>;

export const InputText = forwardRef<HTMLInputElement, InputTextProps>(
  function InputTextWithRef(
    {
      className,
      style,
      error,
      success,
      filled,
      icon,
      placeholder,
      inputClass,
      messageClass,
      message,
      activeLabel = true,
      inputSize = 'm',
      ...rest
    }: InputTextProps,
    ref
  ) {
    const accent = getAccent({ error, success });
    const { onChange } = useForm();

    const [containerEl, setContainerEl] = useState<HTMLDivElement | null>();
    const containerRef = createRef<HTMLDivElement>();
    const hasIcon = !!icon;
    const hasMessage = !!message;

    useEffect(() => {
      setContainerEl(containerRef.current);
    }, []);

    return (
      <div
        ref={containerRef}
        className={classNames(
          styles.container,
          (hasIcon || hasMessage) && styles.inputTextWithIcon,
          hasIcon && hasMessage && styles.twoIcons,
          className
        )}
        style={style}
      >
        <input
          ref={ref}
          className={classNames(
            styles.inputText,
            filled && styles.filled,
            accent,
            sizes.inputSizes,
            inputClass
          )}
          data-size={inputSize}
          placeholder={activeLabel ? ' ' : placeholder}
          onChange={onChange || rest.onChange}
          {...rest}
        />
        {/* eslint-disable-next-line jsx-a11y/label-has-associated-control */}
        {activeLabel && <label data-size={inputSize}>{placeholder}</label>}
        <div
          className={classNames(
            styles.iconsHolder,
            !hasIcon && !hasMessage && styles.hide
          )}
        >
          {!!message && (
            <NoticeTooltip
              content={{ message }}
              accent={Accent.negative}
              trigger="mouseenter focus, focusin"
              hideOnClick={false}
              triggerTarget={containerEl}
            >
              <div className={styles.errorIconWrapper}>
                <Icon of="info-exclamation" className={styles.errorIcon} />
              </div>
            </NoticeTooltip>
          )}
          {icon}
        </div>
      </div>
    );
  }
);
